head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setCellInputType]<br/>inputType='custom' 인 Column 의 특정 Body Cell 에 inputType 속성을 설정합니다.",
    "validation" : [
        "info.itemSet(선택) 파라미터로 ItemSet 기반 Cell 인 경우 아이템과 바인딩 되는 DataList 정보를 객체로 설정할 수 있어야 합니다.",
        "info.itemSet(선택) 파라미터는 info.inputType 파라미터값이 'select', 'checkcombobox', 'autoComplete' 인 경우 설정합니다.",
        "info.itemSet.nodeset(필수) 파라미터로 아이템이 정의된 DataList 의 ID 를 'data:[DataList ID]' 형식으로 설정할 수 있어야 합니다.",
        "info.itemSet.label(필수) 파라미터로 아이템의 Label 값으로 바인딩할 Column 의 ID 를 설정할 수 있어야 합니다.",
        "info.itemSet.value(필수) 파라미터로 아이템의 Value 값으로 바인딩할 Column 의 ID 를 설정할 수 있어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof dlt_item !== 'undefined') {
        $p.data.remove("dlt_item");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] col1 은 inputType=custom + setCellInputTypeCustom=true (typeGetter 미설정) -> setCellInputType 동작 대상. rowIndex/columnInfo 는 0,0 고정.\n[아이템 DataList] dlt_item : Label 컬럼=col1(서울/부산/대구), Value 컬럼=col2(01/02/03).\n[절차] info.inputType(ItemSet 기반 select/checkcombobox/autoComplete) 과 info.itemSet 설정 여부 선택 후 setCellInputType 실행. itemSet=설정 시 nodeset:data:dlt_item, label:col1, value:col2 로 바인딩.\n[확인] 해당 Cell(0,0) 을 더블클릭(편집)하면 itemSet(dlt_item) 아이템(서울/부산/대구)이 select 드롭다운에 표시됨. itemSet=미설정(생략) 시 기본값(undefined) 동작."', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();

    // itemSet 바인딩용 DataList (ItemSet 기반 inputType : select/checkcombobox/autoComplete 용)
    //  ※ createBasicDataList 는 col1~col4 스키마만 생성하므로 itemSet 의 label/value 도 col1/col2 를 사용한다.
    //    (col1=표시 라벨, col2=실제 값)
    $c.gcm.createBasicDataList('', '', 'dlt_item');
    dlt_item.setJSON([
        { "col1": "서울", "col2": "01" },
        { "col1": "부산", "col2": "02" },
        { "col1": "대구", "col2": "03" }
    ]);

    // 본문 DataList (custom 셀 편집용, 초기값 빈값)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "" },
        { "col1": "" },
        { "col1": "" },
        { "col1": "" }
    ]);

    // target 생성
    //  - setCellInputTypeCustom="true" : custom 컬럼의 Cell 단위 inputType 변경 허용
    //  - Body 컬럼은 inputType="custom" + typeGetter 미설정 (전제). id/dataList 는 col1 (바인딩 DataList 컬럼과 일치).
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" setCellInputTypeCustom="true" dataList="data:dlt_bind" id="" style="width:420px;height:200px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="*" inputType="text" id="hcol0" value="col1 (custom)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="*" inputType="custom" displayMode="label" value="" id="col1" dataList="col1"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// 해당 Cell 을 편집모드(더블클릭과 동일)로 진입시켜 실제로 selectbox 가 셀에 표시되는지 확인한다.
scwin.isSelectboxShown = function (rowIndex, columnInfo) {
    let api = scwin.target1;
    let colIndex = api.getColumnIndex(columnInfo);
    let td = api._getTDByIndex(colIndex + (rowIndex - (api.rowIndex > 0 ? api.rowIndex : 0)) * api.oneRowDataLength);
    // 실제 더블클릭과 동일한 편집모드 진입 경로(mainDrawController.setEditMode) 사용 -> 정상 selectbox 생성
    try { if (td && typeof api.setEditMode === 'function') api.setEditMode(td); } catch (e) {}
    return !!(td && td.querySelector('[role=combobox]'));
};



scwin.btn_setCellInputType_onclick = function () {
    // rowIndex / columnInfo 는 0, 0 고정 (이 샘플은 info.itemSet 검증 전용)
    let rowIndex = 0;
    let columnInfo = 0;
    let inputType = par_inputType.getValue();

    // info 객체 구성
    //  - info.inputType : 필수 (ItemSet 기반 타입 : select/checkcombobox/autoComplete)
    //  - info.itemSet   : nodeset(DataList ID) / label(Label Column ID) / value(Value Column ID)
    let info = {
        inputType: inputType,
        options: { viewType: "default" },
        itemSet: {
            nodeset: "data:dlt_item",  // 아이템이 정의된 DataList ID ('data:dlt_item')
            label: "col1",             // 아이템 Label 로 바인딩할 Column ID
            value: "col2"              // 아이템 Value 로 바인딩할 Column ID
        }
    };

    // 메소드 실행
    scwin.target1.setCellInputType(rowIndex, columnInfo, info);

    // 셀 단위 재렌더 (교체된 입력 컴포넌트 표시)
    try { scwin.target1.refreshCell(rowIndex, columnInfo); } catch (e) {}

    // 셀에 selectbox 가 표시되는지 여부 (더블클릭과 동일한 편집모드 진입)
    let shown = scwin.isSelectboxShown(rowIndex, columnInfo);

    wf_body_bottom.getObj("scwin").setReturnValue(
        "setCellInputType(0, 0, { inputType:'" + inputType + "', itemSet:{...} })"
        + " | info.itemSet(바인딩 정보) : { nodeset:'data:dlt_item', label:'col1', value:'col2' }"
        + " | 셀에 selectbox 표시 여부 : " + (shown ? "표시됨 (O)" : "미표시 (X)"));
}
